<section class="rounded-2xl border border-brand-border bg-brand-canvas p-5" aria-label="Payment breakdown" data-price-breakdown>
    <h3 class="text-base font-bold text-slate-950">Payment breakdown</h3>
    <p class="mt-1 text-xs text-slate-600">Calculated from the selected category and membership level. Final pricing is verified when saved.</p>
    <dl class="mt-4 grid gap-3 text-sm sm:grid-cols-2">
        <div class="flex justify-between gap-3"><dt class="text-slate-600">Original fee</dt><dd class="font-semibold text-slate-900" data-price-original>—</dd></div>
        <div class="flex justify-between gap-3"><dt class="text-slate-600">Discount</dt><dd class="font-semibold text-slate-900" data-price-percent>—</dd></div>
        <div class="flex justify-between gap-3"><dt class="text-slate-600">Discount amount</dt><dd class="font-semibold text-slate-900" data-price-discount>—</dd></div>
        <div class="flex justify-between gap-3 border-t border-brand-border pt-3 sm:border-t-0 sm:pt-0"><dt class="font-bold text-slate-900">Final amount due</dt><dd class="font-bold text-brand-primary" data-price-due>—</dd></div>
    </dl>
</section>
